        self.aapl_rsi = self.RSI(self.aapl, self.RSI_PERIOD, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {
            "A": None,
            "B": None
        }

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data):
        self._apply_splits(data)

        spy_buy_cross, spy_sell_cross = self._update_spy_state(data)
        aapl_red_three_days = self._update_aapl_state(data)

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if self.IsWarmingUp:
            return

        aapl_rsi_above_60 = (
            self.aapl_rsi.IsReady and
            float(self.aapl_rsi.Current.Value) > 60.0
        )

        # Evaluate all sell reasons before any buy reasons.
        if (
            self.lots["A"] > 0 and
            self.pending_orders["A"] is None and
            spy_sell_cross
        ):
            self._submit_sell("A", self.spy)

        if (
            self.lots["B"] > 0 and
            self.pending_orders["B"] is None and
            aapl_rsi_above_60
        ):
            self._submit_sell("B", self.aapl)

        # Slot 1: Strategy A
        if (
            self.lots["A"] == 0 and
            self.pending_orders["A"] is None and
            spy_buy_cross
        ):
            close = float(data.Bars[self.spy].Close)
            portfolio_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int(math.floor((0.40 * portfolio_value) / close))

            if quantity > 0:
                self._submit_buy("A", self.spy, quantity)

        # Slot 2: Strategy B
        if (
            self.lots["B"] == 0 and
            self.pending_orders["B"] is None and
            aapl_red_three_days
        ):
            available_cash = float(self.Portfolio.Cash)

            if available_cash >= self.AAPL_BUY_AMOUNT:
                close = float(data.Bars[self.aapl].Close)
                quantity = int(math.floor(self.AAPL_BUY_AMOUNT / close))

