        if self.spy not in data.Bars:
            return False, False

        bar = data.Bars[self.spy]
        close = float(bar.Close)

        previous_close = self.previous_spy_close
        previous_sma = self.previous_spy_sma

        current_sma = None
        if self.spy_sma.IsReady:
            current_sma = float(self.spy_sma.Current.Value)

        buy_cross = (
            previous_close is not None and
            previous_sma is not None and
            current_sma is not None and
            previous_close <= previous_sma and
            close > current_sma
        )

        sell_cross = (
            previous_close is not None and
            previous_sma is not None and
            current_sma is not None and
            previous_close >= previous_sma and
            close < current_sma
        )

        self.previous_spy_close = close
        if current_sma is not None:
            self.previous_spy_sma = current_sma

        return buy_cross, sell_cross

    def _update_aapl_state(self, data):
        if self.aapl not in data.Bars:
            return False

        close = float(data.Bars[self.aapl].Close)

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        self.previous_aapl_close = close
        return self.aapl_red_streak >= 3

    def _apply_splits(self, data):
        if self.aapl in data.Splits and self.lots["B"] > 0:
            split_factor = float(data.Splits[self.aapl].SplitFactor)
            if split_factor > 0:
                self.lots["B"] = int(self.lots["B"] * split_factor)

        if self.spy in data.Splits and self.lots["A"] > 0:
            split_factor = float(data.Splits[self.spy].SplitFactor)
            if split_factor > 0:
                self.lots["A"] = int(self.lots["A"] * split_factor)

    def _submit_buy(self, slot, symbol, quantity):
        tag = "{}_BUY".format(slot)
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        self.pending_orders[slot] = ticket.OrderId

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = None

    def _submit_sell(self, slot, symbol):
        quantity = self.lots[slot]
        if quantity <= 0:
            return

        tag = "{}_SELL".format(slot)
        ticket = self.MarketOrder(symbol, -quantity, tag=tag)

        self.pending_orders[slot] = ticket.OrderId

        if ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            self.pending_orders[slot] = None

    def OnOrderEvent(self, order_event):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        if tag not in ("A_BUY", "A_SELL", "B_BUY", "B_SELL"):
            return

        slot = tag[0]
        side = tag[2:]
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if side == "BUY":
                self.lots[slot] += max(0, fill_quantity)
            elif side == "SELL":
                self.lots[slot] = max(0, self.lots[slot] + fill_quantity)

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            if self.pending_orders[slot] == order_event.OrderId:
                self.pending_orders[slot] = None
