from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Indicators import MovingAverageType
from QuantConnect.Orders import OrderStatus


class DailyCrossAndMomentumAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(30, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars

        spy_bar = bars[self.spy] if self.spy in bars else None
        aapl_bar = bars[self.aapl] if self.aapl in bars else None

        current_spy_close = None
        current_spy_sma = None
        if spy_bar is not None:
            current_spy_close = float(spy_bar.Close)
            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

        current_aapl_close = None
        current_aapl_rsi = None
        if aapl_bar is not None:
            current_aapl_close = float(aapl_bar.Close)
            if self.aapl_rsi.IsReady:
                current_aapl_rsi = float(self.aapl_rsi.Current.Value)

        current_aapl_red_streak = self.aapl_red_streak
        if current_aapl_close is not None:
            if self.previous_aapl_close is None:
                current_aapl_red_streak = 0
            elif current_aapl_close < self.previous_aapl_close:
                current_aapl_red_streak = self.aapl_red_streak + 1
            else:
                current_aapl_red_streak = 0

        all_bars_present = all(symbol in bars for symbol in self.required_symbols)

        if (
            not self.IsWarmingUp
            and all_bars_present
            and current_spy_close is not None
            and current_spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and current_aapl_close is not None
            and current_aapl_rsi is not None
        ):
            spy_crosses_above_sma = (
                self.previous_spy_close <= self.previous_spy_sma
                and current_spy_close > current_spy_sma
            )

            spy_crosses_below_sma = (
                self.previous_spy_close >= self.previous_spy_sma
                and current_spy_close < current_spy_sma
            )

            aapl_rsi_above_60 = current_aapl_rsi > 60
            aapl_red_for_three_days = current_aapl_red_streak >= 3

            if self.spy_lot > 0 and spy_crosses_below_sma:
                self._sell_spy_lot()

            if self.aapl_lot > 0 and aapl_rsi_above_60:
                self._sell_aapl_lot()

            if self.spy_lot == 0 and spy_crosses_above_sma:
                self._buy_spy_lot(current_spy_close)

            if self.aapl_lot == 0 and aapl_red_for_three_days:
                self._buy_aapl_lot(current_aapl_close)

        if spy_bar is not None:
            self.previous_spy_close = current_spy_close
            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if aapl_bar is not None:
            self.previous_aapl_close = current_aapl_close
            self.aapl_red_streak = current_aapl_red_streak

    def _buy_spy_lot(self, close):
        quantity = int(
            (0.40 * float(self.Portfolio.TotalPortfolioValue)) / close
        )

        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.spy, quantity)
        if ticket is not None and ticket.Status != OrderStatus.Invalid:
            self.spy_lot = quantity

    def _sell_spy_lot(self):
        if self.spy_lot <= 0:
            return

        ticket = self.MarketOrder(self.spy, -self.spy_lot)
        if ticket is not None and ticket.Status != OrderStatus.Invalid:
            self.spy_lot = 0

    def _buy_aapl_lot(self, close):
        if float(self.Portfolio.Cash) < 20000:
            return

        quantity = int(20000 / close)

        if quantity <= 0:
            return

        ticket = self.MarketOrder(self.aapl, quantity)
        if ticket is not None and ticket.Status != OrderStatus.Invalid:
            self.aapl_lot = quantity

    def _sell_aapl_lot(self):
        if self.aapl_lot <= 0:
            return

        ticket = self.MarketOrder(self.aapl, -self.aapl_lot)
        if ticket is not None and ticket.Status != OrderStatus.Invalid:
            self.aapl_lot = 0

