    RSI_PERIOD = 14
    AAPL_BUY_AMOUNT = 20000.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(
            self.spy,
            self.SMA_PERIOD,
            Resolution.Daily
        )

        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_by_symbol = {}
        self.order_to_lot = {}
        self.order_events_seen = set()
        self.fallback_fills = set()

        self.SetWarmUp(self.SMA_PERIOD, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars

        spy_cross_above = False
        spy_cross_below = False

        if bars.ContainsKey(self.spy):
            spy_bar = bars[self.spy]
            spy_close = float(spy_bar.Close)

            if self.spy_sma.IsReady:
                current_sma = float(self.spy_sma.Current.Value)

                if (
                    self.spy_previous_close is not None
                    and self.spy_previous_sma is not None
                ):
                    spy_cross_above = (
                        self.spy_previous_close <= self.spy_previous_sma
                        and spy_close > current_sma
                    )

                    spy_cross_below = (
                        self.spy_previous_close >= self.spy_previous_sma
                        and spy_close < current_sma
                    )

                self.spy_previous_close = spy_close
                self.spy_previous_sma = current_sma

        if bars.ContainsKey(self.aapl):
            aapl_close = float(bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        complete_day = all(bars.ContainsKey(symbol) for symbol in self.symbols)

        if not complete_day or self.IsWarmingUp:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.spy_previous_close is None or self.spy_previous_sma is None:
            return

        aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60.0
        aapl_red_for_three_days = self.aapl_red_streak >= 3

        if self.lots["A"] > 0 and spy_cross_below:
            self._submit_order(
                "A",
                self.spy,
                -self.lots["A"],
                "Strategy A sell"
            )

        if self.lots["B"] > 0 and aapl_rsi_above_60:
            self._submit_order(
                "B",
                self.aapl,
                -self.lots["B"],
                "Strategy B sell"
            )

        if self.lots["A"] == 0 and "A" not in self.pending_by_symbol.values():
            if spy_cross_above:
                spy_close = float(bars[self.spy].Close)
                target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self._submit_order(
                        "A",
                        self.spy,
                        quantity,
                        "Strategy A buy"
                    )

        if self.lots["B"] == 0 and "B" not in self.pending_by_symbol.values():
            if aapl_red_for_three_days:
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= self.AAPL_BUY_AMOUNT:
                    aapl_close = float(bars[self.aapl].Close)
                    quantity = int(self.AAPL_BUY_AMOUNT / aapl_close)

                    if quantity > 0:
                        self._submit_order(
                            "B",
                            self.aapl,
                            quantity,
                            "Strategy B buy"
                        )

    def _submit_order(self, lot_name, symbol, quantity, tag):
        if quantity == 0:
            return False

        if symbol in self.pending_by_symbol:
            return False

        self.pending_by_symbol[symbol] = lot_name

        ticket = self.MarketOrder(
            symbol,
            quantity,
            asynchronous=False,
            tag=tag
        )

        if ticket is None:
            if self.pending_by_symbol.get(symbol) == lot_name:
                del self.pending_by_symbol[symbol]
            return False

        order_id = ticket.OrderId
        self.order_to_lot[order_id] = lot_name

        if ticket.Status == OrderStatus.Filled:
            if order_id not in self.order_events_seen:
                self.lots[lot_name] += int(quantity)
                self.fallback_fills.add(order_id)

            if self.pending_by_symbol.get(symbol) == lot_name:
                del self.pending_by_symbol[symbol]

            return True

